-- SIGIA-AMINE — Étape 17 : Restauration
begin;
select plan(36);
select has_table('public','meal_types','meal_types existe');
select has_table('public','menus','menus existe');
select has_table('public','menu_items','menu_items existe');
select has_table('public','meal_service_records','meal_service_records existe');
select has_table('public','meal_attendance','meal_attendance existe');
select has_table('public','catering_menu_ingredients','ingredients restauration existe');
select has_table('public','catering_consumptions','consommations restauration existe');
select has_table('public','catering_purchase_links','liens achats restauration existent');
select has_function('public','create_meal_type',array['uuid','text','text','integer'],'RPC type repas');
select has_function('public','create_catering_menu',array['uuid','date','text'],'RPC menu');
select has_function('public','upsert_catering_menu_item',array['uuid','uuid','text','numeric','numeric','text','text'],'RPC ligne menu');
select has_function('public','publish_catering_menu',array['uuid'],'RPC publication menu');
select has_function('public','close_catering_menu',array['uuid'],'RPC clôture menu');
select has_function('public','upsert_catering_ingredient',array['uuid','uuid','numeric','text','text'],'RPC ingrédient');
select has_function('public','record_catering_service',array['uuid','numeric','text','numeric','text'],'RPC service');
select has_function('public','set_meal_attendance',array['uuid','uuid','date','boolean','numeric','text'],'RPC présence repas');
select has_function('public','consume_catering_stock',array['uuid','uuid','uuid','numeric','numeric','text'],'RPC consommation stock');
select has_function('public','link_catering_purchase',array['uuid','uuid','uuid','numeric'],'RPC lien achat');
select has_function('public','get_catering_dashboard',array['uuid','date'],'RPC dashboard');
select has_index('public','meal_types','ux_meal_types_school_lower_code','unicité type repas par école');
select has_index('public','menu_items','ux_menu_items_menu_meal_type','un seul repas par type et date/menu');
select has_index('public','meal_attendance','ix_meal_attendance_school_date_meal','index présences repas');
select has_index('public','catering_consumptions','ix_catering_consumptions_school_date','index consommations');
select ok(exists(select 1 from pg_constraint where conrelid='public.menus'::regclass and conname='menus_status_ck' and contype='c'),'statut menu contrôlé');
select ok(exists(select 1 from pg_constraint where conrelid='public.meal_service_records'::regclass and conname='meal_service_records_status_ck' and contype='c'),'statut service contrôlé');
select ok(exists(select 1 from pg_constraint where conrelid='public.meal_attendance'::regclass and conname='meal_attendance_qty_ck' and contype='c'),'quantité repas contrôlée');
select policies_are('public','menus',array['menus_select_secure'],'menus : lecture via RBAC');
select policies_are('public','menu_items',array['menu_items_select_secure'],'lignes de menu : lecture via RBAC');
select policies_are('public','meal_service_records',array['meal_service_records_select_secure'],'service repas : lecture via RBAC');
select policies_are('public','meal_attendance',array['meal_attendance_select_secure'],'présence repas : lecture sécurisée');
select policies_are('public','catering_menu_ingredients',array['catering_ingredients_select_secure'],'ingredients : lecture sécurisée');
select ok((select not exists(select 1 from information_schema.role_table_grants where grantee='authenticated' and table_schema='public' and table_name='meal_attendance' and privilege_type='INSERT')),'pas d insertion directe présences');
select ok((select not exists(select 1 from information_schema.role_table_grants where grantee='authenticated' and table_schema='public' and table_name='meal_service_records' and privilege_type='INSERT')),'pas d insertion directe services');
select ok((select not exists(select 1 from information_schema.role_table_grants where grantee='authenticated' and table_schema='public' and table_name='catering_consumptions' and privilege_type='INSERT')),'pas d insertion directe consommations');
select ok((select exists(select 1 from information_schema.routines where routine_schema='public' and routine_name='consume_catering_stock')),'consommation stock centralisée');
select has_function('public','get_student_catering',array['uuid'],'sous-dossier restauration élève');
select * from finish();
rollback;
